RKfill("bs",[{"b":["Bootstrap adalah framework CSS dengan <b>komponen siap pakai</b> (tombol, kartu, navbar, modal) dan sistem grid. Versi 5 tidak lagi membutuhkan jQuery.","Cara cepat: tambahkan CSS di <code>&lt;head&gt;</code> dan bundle JS di akhir <code>&lt;body&gt;</code> dari CDN jsDelivr: <code>bootstrap@5.3.3/dist/css/bootstrap.min.css</code> dan <code>bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js</code>. Bundle sudah berisi Popper untuk dropdown dan tooltip.","Lewat npm: <code>npm install bootstrap</code>, lalu <code>import \"bootstrap/dist/css/bootstrap.min.css\"</code> dan <code>import \"bootstrap\"</code> di file JS utama.","Pratinjau di halaman ini sudah memuat Bootstrap 5.3, jadi kamu cukup menulis HTML."],"html":"<div class=\"container py-4\">\n  <h1 class=\"display-6\">Toko Nusantara</h1>\n  <p class=\"lead\">Kopi, teh, dan camilan pilihan.</p>\n  <button class=\"btn btn-primary\">Belanja sekarang</button>\n</div>","bs":true,"task":{"q":"Ubah tombol menjadi hijau dengan mengganti <code>btn-primary</code> menjadi <code>btn-success</code>.","test":"document.querySelector('.btn').classList.contains('btn-success')","hint":"Ganti nama kelas btn-primary menjadi btn-success."},"pts":["Bootstrap 5 = komponen + grid + utilitas, tanpa jQuery.","CSS di head, bootstrap.bundle.min.js di akhir body."],"q":[["Apa isi bootstrap.bundle.min.js selain JS Bootstrap?",["Popper","jQuery","React"],0,"Popper dibutuhkan dropdown, tooltip, dan popover."],["Apakah Bootstrap 5 memerlukan jQuery?",["Tidak","Ya","Hanya untuk grid"],0,"Sejak v5 Bootstrap memakai JavaScript biasa."]],"so":[{"q":"Tulis kerangka HTML lengkap yang memuat Bootstrap 5.3.3 dari CDN jsDelivr.","h":"link CSS di head, script bundle sebelum &lt;/body>, dan meta viewport.","a":"<!doctype html>\n<html lang=\"id\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Toko</title>\n  <link href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css\" rel=\"stylesheet\">\n</head>\n<body>\n  <h1 class=\"container\">Halo, Bootstrap!</h1>\n  <script src=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js\"></script>\n</body>\n</html>","lang":"html"},{"q":"Buat tiga tombol berdampingan: Simpan (primary), Batal (outline-secondary), Hapus (danger, kecil).","h":"btn btn-primary, btn btn-outline-secondary, btn btn-danger btn-sm.","a":"<div class=\"d-flex gap-2\">\n  <button class=\"btn btn-primary\">Simpan</button>\n  <button class=\"btn btn-outline-secondary\">Batal</button>\n  <button class=\"btn btn-danger btn-sm\">Hapus</button>\n</div>","lang":"html"}],"deep":{"ist":[["CDN","Memuat CSS/JS dari jsDelivr; cepat untuk prototipe."],["npm + bundler","Cara produksi: npm i bootstrap, impor Sass dan hanya JS yang diperlukan."],["bootstrap.bundle.js","Berisi Popper.js untuk dropdown, tooltip, dan popover."],["SRI (integrity)","Hash yang memastikan file dari CDN tidak diubah pihak lain."],["Bootstrap Icons","Pustaka 2.000+ ikon SVG resmi."]],"cx":[{"t":"Templat awal dengan CDN","code":"<!doctype html>\n<html lang=\"id\" data-bs-theme=\"light\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Kursus Coding</title>\n  <link href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css\" rel=\"stylesheet\"\n        integrity=\"sha384-QWTKZyjpPEjISv5WaRU9OFeRpok6YctnYmDr5pNlyT2bRjXh0JMhjY6hW+ALEwIH\" crossorigin=\"anonymous\">\n  <link href=\"https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css\" rel=\"stylesheet\">\n</head>\n<body>\n  <main class=\"container py-5\">\n    <h1 class=\"display-5 fw-bold\">Halo, Bootstrap!</h1>\n    <button class=\"btn btn-primary\"><i class=\"bi bi-rocket-takeoff\"></i> Mulai</button>\n  </main>\n  <script src=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js\"\n          integrity=\"sha384-YvpcrYf0tY3lHB60NNkmXc5s9fDVZLESaAA55NDzOxhy9GkcIdslK1eN7N6jIeHz\" crossorigin=\"anonymous\"></script>\n</body>\n</html>","lang":"html"},{"t":"Instalasi produksi dengan Vite dan Sass","code":"npm i bootstrap @popperjs/core && npm i -D sass\n\n// src/main.js: impor hanya komponen JS yang dipakai\nimport \"./style.scss\";\nimport Modal from \"bootstrap/js/dist/modal\";\nimport Collapse from \"bootstrap/js/dist/collapse\";\n\n// src/style.scss: impor hanya bagian Sass yang dipakai\n@import \"bootstrap/scss/functions\";\n@import \"bootstrap/scss/variables\";\n@import \"bootstrap/scss/maps\";\n@import \"bootstrap/scss/mixins\";\n@import \"bootstrap/scss/root\";\n@import \"bootstrap/scss/reboot\";\n@import \"bootstrap/scss/grid\";\n@import \"bootstrap/scss/buttons\";\n@import \"bootstrap/scss/utilities/api\";","lang":"bash"},{"t":"Membuat hash SRI untuk file sendiri","code":"import { createHash } from \"node:crypto\";\nconst isi = \"/* app.css */ .kartu{border-radius:12px}\";\nconst sri = \"sha384-\" + createHash(\"sha384\").update(isi).digest(\"base64\");\nconsole.log(`<link rel=\"stylesheet\" href=\"https://cdn.contoh.id/app.css\" integrity=\"${sri}\" crossorigin=\"anonymous\">`);\nconst diubah = isi.replace(\"12px\", \"0\");\nconsole.log(\"file diubah penyerang -> hash cocok?\", sri === \"sha384-\" + createHash(\"sha384\").update(diubah).digest(\"base64\"), \"(browser menolak memuat)\");","lang":"js","out":"<link rel=\"stylesheet\" href=\"https://cdn.contoh.id/app.css\" integrity=\"sha384-lS8hWZMgbfvP/yfgK5qJ+R4Lv4E8VBQTI20fvi1XXEdTxXspDJpSfcEDiNBbW30Y\" crossorigin=\"anonymous\">\nfile diubah penyerang -> hash cocok? false (browser menolak memuat)"}]}},{"b":["Grid Bootstrap terdiri dari <code>.container</code> → <code>.row</code> → <code>.col</code>. Setiap baris dibagi 12 kolom.","<code>col-4</code> mengambil 4 dari 12 kolom (sepertiga). Tambahkan titik henti: <code>col-12 col-md-6 col-lg-4</code> berarti penuh di ponsel, setengah mulai 768px, sepertiga mulai 992px.","Titik henti Bootstrap: <code>sm</code> 576px, <code>md</code> 768px, <code>lg</code> 992px, <code>xl</code> 1200px, <code>xxl</code> 1400px. Jarak antarkolom diatur dengan <code>g-3</code> (gutter)."],"html":"<div class=\"container py-3\">\n  <div class=\"row g-3\">\n    <div class=\"col-12 col-md-6\"><div class=\"p-3 bg-info-subtle border rounded\">Dart</div></div>\n    <div class=\"col-12 col-md-6\"><div class=\"p-3 bg-info-subtle border rounded\">Kotlin</div></div>\n    <div class=\"col-12 col-md-6\"><div class=\"p-3 bg-info-subtle border rounded\">Flutter</div></div>\n    <div class=\"col-12 col-md-6\"><div class=\"p-3 bg-info-subtle border rounded\">Compose</div></div>\n  </div>\n</div>","bs":true,"task":{"q":"Buat setiap kolom menjadi sepertiga lebar di layar besar: tambahkan <code>col-lg-4</code> pada keempat kolom.","test":"[...document.querySelectorAll('.row > div')].every(d=>d.classList.contains('col-lg-4'))","hint":"Tambahkan col-lg-4 setelah col-md-6 di setiap div kolom."},"pts":["container → row → col.","12 kolom per baris; col-md-6 = setengah mulai md.","Gutter: g-0 sampai g-5."],"q":[["Berapa lebar col-3 dalam baris 12 kolom?",["Seperempat","Sepertiga","Setengah"],0,"3/12 = 1/4."],["Titik henti lg di Bootstrap 5 mulai lebar?",["768px","992px","1200px"],1,"sm 576, md 768, lg 992, xl 1200, xxl 1400."]],"so":[{"q":"Buat tata letak sidebar 3 kolom dan konten 9 kolom mulai md, ditumpuk di ponsel.","h":"row lalu col-md-3 dan col-md-9.","a":"<div class=\"container\">\n  <div class=\"row g-3\">\n    <aside class=\"col-md-3\"><div class=\"p-3 bg-light border\">Menu</div></aside>\n    <main class=\"col-md-9\"><div class=\"p-3 border\">Konten</div></main>\n  </div>\n</div>","lang":"html"},{"q":"Buat satu kolom selebar 6 yang berada di tengah baris.","h":"offset-3 menggeser kolom 3 satuan, atau justify-content-center pada row.","a":"<div class=\"row justify-content-center\">\n  <div class=\"col-6\"><div class=\"p-3 border text-center\">Tengah</div></div>\n</div>","lang":"html"}],"deep":{"ist":[["container / container-fluid","Pembungkus dengan lebar maksimum per breakpoint atau penuh."],["row & col","Baris flex berisi kolom; total 12 bagian per baris."],["Breakpoint","sm 576, md 768, lg 992, xl 1200, xxl 1400 px."],["Gutter (g-*)","Jarak antar kolom: g-0 sampai g-5, gx-* dan gy-*."],["row-cols-*","Menentukan jumlah kolom per baris tanpa menulis col-* di setiap anak."]],"cx":[{"t":"Tata letak blog dan galeri kartu","code":"<div class=\"container py-4\">\n  <div class=\"row g-4\">\n    <main class=\"col-lg-8\">Artikel</main>\n    <aside class=\"col-lg-4\">Sidebar</aside>             <!-- menumpuk di bawah lg -->\n  </div>\n\n  <div class=\"row row-cols-1 row-cols-sm-2 row-cols-lg-4 g-3 mt-2\">\n    <div class=\"col\"><div class=\"card h-100\">...</div></div>\n    <div class=\"col\"><div class=\"card h-100\">...</div></div>\n    <div class=\"col\"><div class=\"card h-100\">...</div></div>\n    <div class=\"col\"><div class=\"card h-100\">...</div></div>\n  </div>\n\n  <div class=\"row\">\n    <div class=\"col-md-6 offset-md-3 text-center\">Konten di tengah</div>\n    <div class=\"col-6 col-md-4 order-md-2\">A</div>\n    <div class=\"col-6 col-md-8 order-md-1\">B</div>\n  </div>\n</div>","lang":"html"},{"t":"Menghitung lebar kolom di setiap breakpoint","code":"const container = { xs: null, sm: 540, md: 720, lg: 960, xl: 1140, xxl: 1320 };\nconst bp = { xs: 0, sm: 576, md: 768, lg: 992, xl: 1200, xxl: 1400 };\nconst gutter = 24;\nfunction lebarKolom(layar, kelas) {\n  const aktif = Object.keys(bp).filter((k) => layar >= bp[k]).at(-1);\n  const wadah = container[aktif] ?? layar;\n  let span = 12;\n  for (const k of Object.keys(bp)) {\n    if (layar < bp[k]) break;\n    const m = kelas.match(new RegExp(`col-${k === \"xs\" ? \"\" : k + \"-\"}(\\\\d+)`));\n    if (m) span = +m[1];\n  }\n  return { aktif, wadah, span, px: Math.round((wadah * span) / 12 - gutter) };\n}\nfor (const w of [375, 800, 1024, 1440]) {\n  const a = lebarKolom(w, \"col-12 col-md-6 col-lg-4\"), b = lebarKolom(w, \"col-12 col-lg-8\");\n  console.log(`${String(w).padStart(4)}px [${a.aktif.padEnd(3)}] wadah ${String(a.wadah).padStart(4)} | kartu col-${a.span} ~${a.px}px | artikel col-${b.span} ~${b.px}px`);\n}","lang":"js","out":" 375px [xs ] wadah  375 | kartu col-12 ~351px | artikel col-12 ~351px\n 800px [md ] wadah  720 | kartu col-6 ~336px | artikel col-12 ~696px\n1024px [lg ] wadah  960 | kartu col-4 ~296px | artikel col-8 ~616px\n1440px [xxl] wadah 1320 | kartu col-4 ~416px | artikel col-8 ~856px"}]}},{"b":["Bootstrap juga punya kelas utilitas: jarak <code>m-3</code>, <code>p-2</code>, <code>mt-4</code>, <code>px-5</code> (skala 0–5), tampilan <code>d-flex</code>, <code>d-none d-md-block</code>, perataan <code>justify-content-between</code>, <code>align-items-center</code>, <code>text-center</code>.","Warna tema: <code>primary</code>, <code>secondary</code>, <code>success</code>, <code>danger</code>, <code>warning</code>, <code>info</code>, <code>light</code>, <code>dark</code>. Dipakai sebagai <code>text-danger</code>, <code>bg-warning</code>, <code>border-success</code>.","Tipografi: <code>display-1</code> sampai <code>display-6</code> untuk judul besar, <code>lead</code> untuk paragraf pembuka, <code>fw-bold</code>, <code>fs-5</code>, <code>text-muted</code>/<code>text-body-secondary</code>."],"html":"<div class=\"container py-3\">\n  <div class=\"d-flex justify-content-between align-items-center p-3 bg-light border rounded\">\n    <span class=\"fw-bold\">Pesanan #1024</span>\n    <span id=\"status\" class=\"badge bg-secondary\">Diproses</span>\n  </div>\n  <p class=\"mt-3 text-body-secondary\">Estimasi tiba: 2 hari.</p>\n</div>","bs":true,"task":{"q":"Ubah status menjadi hijau dengan <code>bg-success</code> menggantikan <code>bg-secondary</code>.","test":"document.getElementById('status').classList.contains('bg-success')","hint":"Ganti bg-secondary pada span#status."},"pts":["Jarak: m-/p- + arah + skala 0–5.","d-flex, justify-content-*, align-items-*.","Warna tema: primary, success, danger, warning, info, dll."],"q":[["Kelas mana yang menyembunyikan elemen di ponsel tapi menampilkannya mulai md?",["d-none d-md-block","d-md-none d-block","hide-md"],0,"d-none untuk semua, lalu d-md-block mulai md."]],"so":[{"q":"Buat bilah ringkasan: teks kiri \"Total belanja\", angka kanan tebal berwarna hijau, sejajar vertikal, padding 3, garis tepi, sudut membulat.","h":"d-flex justify-content-between align-items-center p-3 border rounded; fw-bold text-success.","a":"<div class=\"d-flex justify-content-between align-items-center p-3 border rounded\">\n  <span>Total belanja</span>\n  <span class=\"fw-bold text-success fs-5\">Rp66.150</span>\n</div>","lang":"html"},{"q":"Sembunyikan kolom keterangan di ponsel dan tampilkan mulai lg.","h":"d-none d-lg-block.","a":"<p class=\"d-none d-lg-block text-body-secondary\">Keterangan tambahan untuk layar lebar.</p>","lang":"html"}],"deep":{"ist":[["Spacing utility","m/p + sisi (t, b, s, e, x, y) + ukuran 0-5: mt-3, px-4, mx-auto."],["Display & flex utility","d-none d-md-block, d-flex justify-content-between align-items-center."],["Typography","display-1 sampai 6, lead, fw-bold, text-truncate, text-body-secondary."],["Theme colors","primary, secondary, success, danger, warning, info, light, dark."],["Subtle & emphasis","bg-success-subtle, text-success-emphasis (5.3) untuk latar lembut."]],"cx":[{"t":"Header bagian dengan utilitas","code":"<section class=\"py-5 bg-body-tertiary\">\n  <div class=\"container\">\n    <div class=\"d-flex flex-column flex-md-row justify-content-between align-items-md-center gap-3 mb-4\">\n      <div>\n        <span class=\"badge rounded-pill bg-success-subtle text-success-emphasis\">Baru</span>\n        <h2 class=\"fw-bold mt-2 mb-1\">Kelas Data Analyst</h2>\n        <p class=\"lead text-body-secondary mb-0\">SQL, Excel, Python, dan dashboard.</p>\n      </div>\n      <a href=\"#\" class=\"btn btn-outline-primary px-4\">Lihat semua <i class=\"bi bi-arrow-right\"></i></a>\n    </div>\n    <p class=\"text-truncate\" style=\"max-width: 320px\">Judul sangat panjang yang akan dipotong dengan elipsis bila tidak muat</p>\n    <p class=\"small text-uppercase fw-semibold text-primary\">Label kecil</p>\n  </div>\n</section>","lang":"html"},{"t":"Arti nilai spacing Bootstrap","code":"const spacer = 16;   // $spacer = 1rem\nconst skala = { 0: 0, 1: 0.25, 2: 0.5, 3: 1, 4: 1.5, 5: 3 };\nfor (const [k, f] of Object.entries(skala)) console.log(`m-${k} / p-${k} = ${String(f).padEnd(4)}rem = ${spacer * f}px`);\nconst kelas = \"mt-3 px-4 mb-md-5 mx-auto\";\nconst arti = { m: \"margin\", p: \"padding\" }, sisi = { t: \"-top\", b: \"-bottom\", s: \"-left (start)\", e: \"-right (end)\", x: \" kiri & kanan\", y: \" atas & bawah\", \"\": \"\" };\nfor (const c of kelas.split(\" \")) {\n  const [, prop, s, bp, n] = c.match(/^([mp])([tbsexy]?)-(?:(sm|md|lg|xl|xxl)-)?(\\d|auto)$/);\n  console.log(`${c.padEnd(10)} -> ${arti[prop]}${sisi[s]} = ${n === \"auto\" ? \"auto\" : spacer * skala[n] + \"px\"}${bp ? ` mulai layar ${bp}` : \"\"}`);\n}","lang":"js","out":"m-0 / p-0 = 0   rem = 0px\nm-1 / p-1 = 0.25rem = 4px\nm-2 / p-2 = 0.5 rem = 8px\nm-3 / p-3 = 1   rem = 16px\nm-4 / p-4 = 1.5 rem = 24px\nm-5 / p-5 = 3   rem = 48px\nmt-3       -> margin-top = 16px\npx-4       -> padding kiri & kanan = 24px\nmb-md-5    -> margin-bottom = 48px mulai layar md\nmx-auto    -> margin kiri & kanan = auto"}]}},{"b":["Tombol: <code>btn btn-primary</code>, versi garis tepi <code>btn-outline-primary</code>, ukuran <code>btn-sm</code>/<code>btn-lg</code>.","Kartu: <code>.card</code> berisi <code>.card-img-top</code>, <code>.card-body</code>, <code>.card-title</code>, <code>.card-text</code>.","Alert untuk pesan: <code>alert alert-warning</code>. Badge untuk label kecil: <code>badge text-bg-danger</code>."],"html":"<div class=\"container py-3\">\n  <div class=\"alert alert-warning\">Stok kopi Gayo tinggal sedikit.</div>\n  <div class=\"card\" style=\"max-width:18rem\">\n    <div class=\"card-body\">\n      <h5 class=\"card-title\">Kopi Gayo <span class=\"badge text-bg-danger\">Baru</span></h5>\n      <p class=\"card-text\">Arabika dari Aceh, 250 gram.</p>\n      <a class=\"btn btn-primary\">Rp 85.000</a>\n    </div>\n  </div>\n</div>","bs":true,"task":{"q":"Tambahkan tombol kedua di dalam kartu dengan kelas <code>btn btn-outline-secondary</code>.","test":"!!document.querySelector('.card .btn.btn-outline-secondary')","hint":"Tulis <a class=\"btn btn-outline-secondary\">Detail</a> setelah tombol pertama."},"pts":["btn + btn-{warna} atau btn-outline-{warna}.","card → card-body → card-title/card-text.","alert alert-{warna}; badge text-bg-{warna}."],"q":[["Kelas apa untuk tombol bergaris tepi merah?",["btn btn-outline-danger","btn btn-danger-outline","btn-border-red"],0,"Pola btn-outline-{warna}."],["Atribut untuk tombol penutup alert?",["data-bs-dismiss=\"alert\"","data-close","onclick=\"hide()\""],0,"Sama polanya dengan modal."]],"so":[{"q":"Buat alert sukses yang bisa ditutup dengan tombol silang.","h":"alert alert-success alert-dismissible fade show + button.btn-close data-bs-dismiss=\"alert\".","a":"<div class=\"alert alert-success alert-dismissible fade show\" role=\"alert\">\n  Pesanan berhasil dibuat.\n  <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\" aria-label=\"Tutup\"></button>\n</div>","lang":"html"},{"q":"Buat tiga kartu produk sama tinggi berdampingan mulai md.","h":"row row-cols-1 row-cols-md-3 g-3 dan card h-100.","a":"<div class=\"row row-cols-1 row-cols-md-3 g-3\">\n  <div class=\"col\"><div class=\"card h-100\"><div class=\"card-body\"><h5 class=\"card-title\">Kopi Gayo</h5><p class=\"card-text\">Rp85.000</p></div></div></div>\n  <div class=\"col\"><div class=\"card h-100\"><div class=\"card-body\"><h5 class=\"card-title\">Kopi Toraja</h5><p class=\"card-text\">Rp90.000</p></div></div></div>\n  <div class=\"col\"><div class=\"card h-100\"><div class=\"card-body\"><h5 class=\"card-title\">Kopi Kintamani</h5><p class=\"card-text\">Rp80.000</p></div></div></div>\n</div>","lang":"html"}],"deep":{"ist":[["btn varian","btn-primary, btn-outline-*, btn-link; ukuran btn-sm/btn-lg."],["card","Wadah dengan card-header, card-body, card-footer, card-img-top."],["alert","Pesan kontekstual; alert-dismissible untuk tombol tutup."],["badge","Label kecil untuk status atau jumlah."],["stretched-link","Membuat seluruh kartu dapat diklik lewat satu tautan."]],"cx":[{"t":"Kartu kursus lengkap","code":"<div class=\"card h-100 shadow-sm position-relative\">\n  <img src=\"react.webp\" class=\"card-img-top\" alt=\"Kelas React\" width=\"400\" height=\"225\">\n  <div class=\"card-body\">\n    <div class=\"d-flex gap-2 mb-2\">\n      <span class=\"badge text-bg-primary\">Frontend</span>\n      <span class=\"badge text-bg-warning\">Terlaris</span>\n    </div>\n    <h5 class=\"card-title\"><a href=\"/kelas/react\" class=\"stretched-link text-decoration-none text-reset\">React dari Nol</a></h5>\n    <p class=\"card-text text-body-secondary\">24 materi · 18 jam · proyek toko online</p>\n  </div>\n  <div class=\"card-footer bg-transparent d-flex justify-content-between align-items-center\">\n    <span><del class=\"text-body-secondary small\">Rp599.000</del> <strong>Rp399.000</strong></span>\n    <span class=\"text-warning\">★ 4,8</span>\n  </div>\n</div>\n\n<div class=\"alert alert-success alert-dismissible fade show d-flex gap-2\" role=\"alert\">\n  <i class=\"bi bi-check-circle-fill\"></i>\n  <div>Pembayaran diterima. Akses kelas sudah aktif.</div>\n  <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\" aria-label=\"Tutup\"></button>\n</div>\n\n<button class=\"btn btn-primary\" disabled>\n  <span class=\"spinner-border spinner-border-sm\" aria-hidden=\"true\"></span>\n  <span role=\"status\">Memproses...</span>\n</button>","lang":"html"},{"t":"Menghitung persentase diskon untuk badge","code":"const kelas = [[\"React dari Nol\", 599000, 399000], [\"Python Data\", 450000, 450000], [\"UI/UX Figma\", 750000, 299000]];\nfor (const [nama, normal, promo] of kelas) {\n  const pct = Math.round((1 - promo / normal) * 100);\n  const badge = pct >= 50 ? \"text-bg-danger\" : pct > 0 ? \"text-bg-warning\" : null;\n  console.log(`${nama.padEnd(16)} Rp${promo.toLocaleString(\"id-ID\").padStart(7)}  ${badge ? `<span class=\"badge ${badge}\">-${pct}%</span>` : \"(tanpa badge)\"}`);\n}","lang":"js","out":"React dari Nol   Rp399.000  <span class=\"badge text-bg-warning\">-33%</span>\nPython Data      Rp450.000  (tanpa badge)\nUI/UX Figma      Rp299.000  <span class=\"badge text-bg-danger\">-60%</span>"}]}},{"b":["Navbar Bootstrap otomatis berubah menjadi menu hamburger di layar kecil. Kuncinya: <code>navbar-expand-lg</code> (melebar mulai lg), tombol <code>navbar-toggler</code>, dan wadah <code>collapse navbar-collapse</code>.","Tombol pembuka memakai atribut <code>data-bs-toggle=\"collapse\"</code> dan <code>data-bs-target=\"#menu\"</code>. Tidak perlu menulis JavaScript sendiri, bundle Bootstrap yang menanganinya.","Pratinjau ini sempit, jadi kamu akan melihat tombol hamburger. Klik untuk membuka menu."],"html":"<nav class=\"navbar navbar-expand-lg bg-dark\" data-bs-theme=\"dark\">\n  <div class=\"container-fluid\">\n    <a class=\"navbar-brand\" href=\"#\">RuangKode</a>\n    <button class=\"navbar-toggler\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#menu\" aria-controls=\"menu\" aria-expanded=\"false\" aria-label=\"Buka menu\">\n      <span class=\"navbar-toggler-icon\"></span>\n    </button>\n    <div class=\"collapse navbar-collapse\" id=\"menu\">\n      <ul class=\"navbar-nav\">\n        <li class=\"nav-item\"><a class=\"nav-link active\" href=\"#\">Beranda</a></li>\n        <li class=\"nav-item\"><a class=\"nav-link\" href=\"#\">Kursus</a></li>\n      </ul>\n    </div>\n  </div>\n</nav>","bs":true,"task":{"q":"Tambahkan item menu ketiga \"Masuk\" di dalam <code>.navbar-nav</code>.","test":"document.querySelectorAll('.navbar-nav .nav-item').length>=3","hint":"Salin satu <li class=\"nav-item\">...</li> dan ganti teksnya."},"pts":["navbar-expand-{bp} menentukan kapan menu melebar.","data-bs-toggle=\"collapse\" + data-bs-target=\"#id\"."],"q":[["Atribut apa yang menghubungkan tombol ke menu yang dilipat?",["data-bs-target","data-target-menu","href saja"],0,"data-bs-target berisi selector elemen collapse."]],"so":[{"q":"Ubah navbar agar melebar mulai md (bukan lg) dan menu rata kanan.","h":"navbar-expand-md; tambahkan ms-auto pada ul.navbar-nav.","a":"<nav class=\"navbar navbar-expand-md bg-body-tertiary\">\n  <div class=\"container-fluid\">\n    <a class=\"navbar-brand\" href=\"#\">RuangKode</a>\n    <button class=\"navbar-toggler\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#menu\" aria-controls=\"menu\" aria-expanded=\"false\" aria-label=\"Buka menu\"><span class=\"navbar-toggler-icon\"></span></button>\n    <div class=\"collapse navbar-collapse\" id=\"menu\">\n      <ul class=\"navbar-nav ms-auto\">\n        <li class=\"nav-item\"><a class=\"nav-link\" href=\"#\">Beranda</a></li>\n        <li class=\"nav-item\"><a class=\"nav-link\" href=\"#\">Kursus</a></li>\n      </ul>\n    </div>\n  </div>\n</nav>","lang":"html"}],"deep":{"ist":[["navbar-expand-*","Breakpoint saat navbar berubah dari menu lipat menjadi horizontal."],["navbar-toggler","Tombol hamburger yang membuka collapse."],["collapse","Komponen JS untuk menampilkan/menyembunyikan konten."],["sticky-top / fixed-top","Navbar tetap terlihat saat scroll."],["aria-current=\"page\"","Menandai tautan halaman aktif untuk pembaca layar."]],"cx":[{"t":"Navbar responsif dengan pencarian","code":"<nav class=\"navbar navbar-expand-lg bg-body-tertiary sticky-top border-bottom\">\n  <div class=\"container\">\n    <a class=\"navbar-brand fw-bold\" href=\"/\"><i class=\"bi bi-code-slash\"></i> RuangKode</a>\n    <button class=\"navbar-toggler\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#navUtama\"\n            aria-controls=\"navUtama\" aria-expanded=\"false\" aria-label=\"Buka navigasi\">\n      <span class=\"navbar-toggler-icon\"></span>\n    </button>\n    <div class=\"collapse navbar-collapse\" id=\"navUtama\">\n      <ul class=\"navbar-nav me-auto mb-2 mb-lg-0\">\n        <li class=\"nav-item\"><a class=\"nav-link active\" aria-current=\"page\" href=\"/\">Beranda</a></li>\n        <li class=\"nav-item\"><a class=\"nav-link\" href=\"/kelas\">Kelas</a></li>\n        <li class=\"nav-item\"><a class=\"nav-link\" href=\"/harga\">Harga</a></li>\n      </ul>\n      <form class=\"d-flex gap-2\" role=\"search\">\n        <input class=\"form-control\" type=\"search\" placeholder=\"Cari kelas\" aria-label=\"Cari kelas\">\n        <button class=\"btn btn-outline-success\" type=\"submit\">Cari</button>\n      </form>\n    </div>\n  </div>\n</nav>","lang":"html"}]}},{"b":["Input memakai <code>form-control</code>, pilihan <code>form-select</code>, kotak centang <code>form-check-input</code>, label <code>form-label</code>.","Validasi bawaan: beri form atribut <code>novalidate</code> dan kelas <code>needs-validation</code>. Saat dikirim, tambahkan kelas <code>was-validated</code> agar Bootstrap menampilkan <code>.invalid-feedback</code> di bawah input yang salah.","Kamu juga bisa menandai satu input secara manual dengan <code>is-invalid</code> atau <code>is-valid</code>."],"html":"<form id=\"daftar\" class=\"container py-3 needs-validation\" novalidate>\n  <div class=\"mb-3\">\n    <label for=\"nama\" class=\"form-label\">Nama</label>\n    <input id=\"nama\" class=\"form-control\" required>\n    <div class=\"invalid-feedback\">Nama wajib diisi.</div>\n  </div>\n  <div class=\"mb-3\">\n    <label for=\"kelas\" class=\"form-label\">Kelas</label>\n    <select id=\"kelas\" class=\"form-select\"><option>Flutter</option><option>Compose</option></select>\n  </div>\n  <button class=\"btn btn-primary\">Daftar</button>\n</form>","js":"const f = document.getElementById('daftar');\nf.addEventListener('submit', e => {\n  e.preventDefault();\n  // tandai form agar Bootstrap menampilkan pesan validasi\n  f.classList.add('was-validated');\n  if (f.checkValidity()) console.log('Terkirim:', f.nama.value);\n});","bs":true,"task":{"q":"Tambahkan input email (<code>type=\"email\"</code>, kelas <code>form-control</code>, <code>required</code>) beserta pesan <code>invalid-feedback</code>.","test":"(e=>!!e&&e.required&&e.classList.contains('form-control')&&!!e.parentElement.querySelector('.invalid-feedback'))(document.querySelector('#daftar input[type=email]'))","hint":"Salin blok div.mb-3 untuk Nama, ganti id, label, dan type menjadi email."},"pts":["form-control, form-select, form-check-input, form-label.","novalidate + was-validated menampilkan invalid-feedback."],"q":[["Kelas apa yang membuat Bootstrap menampilkan pesan validasi untuk seluruh form?",["was-validated","is-validated","validate-all"],0,"was-validated dipasang pada form."],["Kelas untuk menandai satu input tidak valid secara manual?",["is-invalid","invalid","has-error"],0,"is-valid untuk yang benar."]],"so":[{"q":"Buat dua field berdampingan (Nama depan, Nama belakang) mulai md memakai grid di dalam form.","h":"div.row.g-3 lalu col-md-6 untuk setiap field.","a":"<form class=\"row g-3\">\n  <div class=\"col-md-6\"><label class=\"form-label\" for=\"dp\">Nama depan</label><input id=\"dp\" class=\"form-control\"></div>\n  <div class=\"col-md-6\"><label class=\"form-label\" for=\"bl\">Nama belakang</label><input id=\"bl\" class=\"form-control\"></div>\n</form>","lang":"html"},{"q":"Buat kotak centang persetujuan yang wajib dicentang, terpisah dari kotak centang langganan berita.","h":"form-check + form-check-input + form-check-label; required hanya pada persetujuan.","a":"<div class=\"form-check\">\n  <input class=\"form-check-input\" type=\"checkbox\" id=\"setuju\" required>\n  <label class=\"form-check-label\" for=\"setuju\">Saya menyetujui pemrosesan data untuk pendaftaran</label>\n  <div class=\"invalid-feedback\">Centang untuk melanjutkan.</div>\n</div>\n<div class=\"form-check\">\n  <input class=\"form-check-input\" type=\"checkbox\" id=\"berita\">\n  <label class=\"form-check-label\" for=\"berita\">Kirimi saya info kelas baru (opsional)</label>\n</div>","lang":"html"}],"deep":{"ist":[["form-control / form-select","Gaya input dan dropdown standar."],["form-floating","Label mengambang di dalam input."],["Validation classes","is-valid / is-invalid dan invalid-feedback untuk pesan."],["needs-validation + novalidate","Pola validasi Bootstrap dengan Constraint Validation API browser."],["input-group","Input dengan awalan/akhiran seperti \"Rp\" atau tombol."]],"cx":[{"t":"Form checkout dengan validasi Bootstrap","code":"<form class=\"row g-3 needs-validation\" novalidate>\n  <div class=\"col-md-6 form-floating\">\n    <input type=\"text\" class=\"form-control\" id=\"nama\" placeholder=\"Nama\" required minlength=\"3\">\n    <label for=\"nama\">Nama penerima</label>\n    <div class=\"invalid-feedback\">Nama minimal 3 huruf.</div>\n  </div>\n  <div class=\"col-md-6\">\n    <label for=\"hp\" class=\"form-label\">Nomor HP</label>\n    <div class=\"input-group has-validation\">\n      <span class=\"input-group-text\">+62</span>\n      <input type=\"tel\" class=\"form-control\" id=\"hp\" pattern=\"8[0-9]{8,11}\" required aria-describedby=\"hpBantu\">\n      <div class=\"invalid-feedback\">Masukkan nomor tanpa 0 di depan, contoh 81234567890.</div>\n    </div>\n    <div id=\"hpBantu\" class=\"form-text\">Untuk konfirmasi pengiriman via WhatsApp.</div>\n  </div>\n  <div class=\"col-md-4\">\n    <label for=\"kodepos\" class=\"form-label\">Kode pos</label>\n    <input class=\"form-control\" id=\"kodepos\" inputmode=\"numeric\" pattern=\"[0-9]{5}\" required>\n    <div class=\"invalid-feedback\">Kode pos 5 digit.</div>\n  </div>\n  <div class=\"col-12 form-check\">\n    <input class=\"form-check-input\" type=\"checkbox\" id=\"setuju\" required>\n    <label class=\"form-check-label\" for=\"setuju\">Saya setuju data dipakai untuk pengiriman</label>\n  </div>\n  <div class=\"col-12\"><button class=\"btn btn-primary w-100 btn-lg\">Bayar</button></div>\n</form>\n<script>\n  document.querySelectorAll(\".needs-validation\").forEach((f) =>\n    f.addEventListener(\"submit\", (e) => {\n      if (!f.checkValidity()) { e.preventDefault(); e.stopPropagation(); f.querySelector(\":invalid\")?.focus(); }\n      f.classList.add(\"was-validated\");\n    }));\n</script>","lang":"html"},{"t":"Pola validasi HTML yang sama diuji di Node","b":"Atribut pattern di HTML otomatis diberi jangkar ^ dan $, jadi \"081234567890\" gagal karena diawali 0.","code":"const aturan = { nama: { minlength: 3 }, hp: { pattern: \"8[0-9]{8,11}\" }, kodepos: { pattern: \"[0-9]{5}\" } };\nconst cek = (nilai, a) => {\n  if (!nilai) return \"valueMissing\";\n  if (a.minlength && nilai.length < a.minlength) return \"tooShort\";\n  if (a.pattern && !new RegExp(`^(?:${a.pattern})$`).test(nilai)) return \"patternMismatch\";\n  return \"valid\";\n};\nconst isian = [{ nama: \"Al\", hp: \"081234567890\", kodepos: \"4011\" }, { nama: \"Alya\", hp: \"81234567890\", kodepos: \"40115\" }];\nfor (const d of isian) console.log(Object.entries(aturan).map(([k, a]) => `${k}=${cek(d[k], a)}`).join(\"  \"));","lang":"js","out":"nama=tooShort  hp=patternMismatch  kodepos=patternMismatch\nnama=valid  hp=valid  kodepos=valid"}]}},{"b":["Modal adalah kotak dialog. Strukturnya <code>.modal</code> → <code>.modal-dialog</code> → <code>.modal-content</code> → header, body, footer.","Membukanya cukup dengan tombol berisi <code>data-bs-toggle=\"modal\"</code> dan <code>data-bs-target=\"#idModal\"</code>. Tombol tutup memakai <code>data-bs-dismiss=\"modal\"</code>.","Komponen lain yang memakai pola sama: dropdown (<code>data-bs-toggle=\"dropdown\"</code>), tooltip, offcanvas, accordion, dan toast. Bisa juga dibuka lewat JS: <code>new bootstrap.Modal(el).show()</code>."],"html":"<div class=\"container py-3\">\n  <button class=\"btn btn-danger\" data-bs-toggle=\"modal\" data-bs-target=\"#konfirmasi\">Hapus akun</button>\n</div>\n<div class=\"modal fade\" id=\"konfirmasi\" tabindex=\"-1\" aria-labelledby=\"judulModal\" aria-hidden=\"true\">\n  <div class=\"modal-dialog\">\n    <div class=\"modal-content\">\n      <div class=\"modal-header\"><h5 class=\"modal-title\" id=\"judulModal\">Yakin?</h5>\n        <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Tutup\"></button></div>\n      <div class=\"modal-body\">Akun yang dihapus tidak bisa dipulihkan.</div>\n      <div class=\"modal-footer\">\n        <button class=\"btn btn-danger\">Ya, hapus</button>\n      </div>\n    </div>\n  </div>\n</div>","bs":true,"task":{"q":"Tambahkan tombol \"Batal\" di footer modal yang menutup modal (<code>data-bs-dismiss=\"modal\"</code>).","test":"!!document.querySelector('.modal-footer [data-bs-dismiss=\"modal\"]')","hint":"Tulis <button class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Batal</button> di .modal-footer."},"pts":["data-bs-toggle=\"modal\" + data-bs-target membuka modal.","data-bs-dismiss=\"modal\" menutupnya.","Bisa juga lewat new bootstrap.Modal(el)."],"q":[["Atribut apa untuk tombol yang menutup modal?",["data-bs-dismiss=\"modal\"","data-bs-close","onclick=\"close()\""],0,"data-bs-dismiss menutup komponen induknya."]],"so":[{"q":"Buka modal lewat JavaScript, bukan atribut data, saat halaman selesai dimuat.","h":"new bootstrap.Modal(elemen).show().","a":"<script>\n  const m = new bootstrap.Modal(document.getElementById('konfirmasi'));\n  m.show();\n</script>","lang":"html"},{"q":"Buat modal yang berada di tengah layar dan tidak tertutup saat area luar diklik.","h":"modal-dialog-centered; data-bs-backdrop=\"static\" pada .modal.","a":"<div class=\"modal fade\" id=\"info\" data-bs-backdrop=\"static\" tabindex=\"-1\" aria-hidden=\"true\">\n  <div class=\"modal-dialog modal-dialog-centered\">\n    <div class=\"modal-content\">\n      <div class=\"modal-body\">Pembayaran sedang diproses.</div>\n      <div class=\"modal-footer\"><button class=\"btn btn-primary\" data-bs-dismiss=\"modal\">Mengerti</button></div>\n    </div>\n  </div>\n</div>","lang":"html"}],"deep":{"ist":[["Data API","Mengaktifkan komponen lewat atribut data-bs-toggle tanpa menulis JS."],["JavaScript API","new bootstrap.Modal(el) dan method show(), hide(), toggle()."],["Event","show.bs.modal, shown.bs.modal, hidden.bs.modal untuk mengaitkan logika."],["getOrCreateInstance","Mengambil instance yang ada atau membuat baru; hindari instance ganda."],["Focus trap","Modal mengunci fokus keyboard di dalamnya dan mengembalikannya saat ditutup."]],"cx":[{"t":"Modal konfirmasi hapus dengan data dinamis","code":"<button class=\"btn btn-outline-danger\" data-bs-toggle=\"modal\" data-bs-target=\"#modalHapus\" data-nama=\"Kelas React\" data-id=\"12\">Hapus</button>\n\n<div class=\"modal fade\" id=\"modalHapus\" tabindex=\"-1\" aria-labelledby=\"judulHapus\" aria-hidden=\"true\">\n  <div class=\"modal-dialog modal-dialog-centered\">\n    <div class=\"modal-content\">\n      <div class=\"modal-header\">\n        <h1 class=\"modal-title fs-5\" id=\"judulHapus\">Hapus kelas?</h1>\n        <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Tutup\"></button>\n      </div>\n      <div class=\"modal-body\">Kelas <strong id=\"namaHapus\"></strong> akan dihapus permanen.</div>\n      <div class=\"modal-footer\">\n        <button class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Batal</button>\n        <button class=\"btn btn-danger\" id=\"konfirmasiHapus\">Ya, hapus</button>\n      </div>\n    </div>\n  </div>\n</div>\n<script>\n  const el = document.getElementById(\"modalHapus\");\n  let idDipilih = null;\n  el.addEventListener(\"show.bs.modal\", (e) => {\n    idDipilih = e.relatedTarget.dataset.id;\n    el.querySelector(\"#namaHapus\").textContent = e.relatedTarget.dataset.nama;   // textContent: aman dari XSS\n  });\n  document.getElementById(\"konfirmasiHapus\").addEventListener(\"click\", async () => {\n    await fetch(`/api/kelas/${idDipilih}`, { method: \"DELETE\" });\n    bootstrap.Modal.getOrCreateInstance(el).hide();\n  });\n</script>","lang":"html"}]}},{"b":["Bootstrap 5.3 menyimpan warna dan ukuran di <b>variabel CSS</b> berawalan <code>--bs-</code>. Kamu bisa menimpanya: <code>:root { --bs-primary: #B4532A; --bs-primary-rgb: 180,83,42; }</code>. Untuk tombol, ubah variabel komponennya, misalnya <code>.btn-primary { --bs-btn-bg: #B4532A; }</code>.","Untuk kustomisasi menyeluruh, pakai <b>Sass</b>: <code>npm install bootstrap sass</code>, lalu di <code>main.scss</code> tulis <code>$primary: #B4532A;</code> sebelum <code>@import \"bootstrap/scss/bootstrap\";</code>. Semua komponen ikut berubah.","Mode gelap: tambahkan <code>data-bs-theme=\"dark\"</code> pada <code>&lt;html&gt;</code> atau pada satu elemen saja."],"html":"<div class=\"container py-3\">\n  <button id=\"utama\" class=\"btn btn-primary\">Tombol utama</button>\n  <div id=\"kotak\" class=\"card mt-3\"><div class=\"card-body\">Kartu ini bisa dibuat gelap.</div></div>\n</div>","css":".btn-primary {\n  --bs-btn-bg: #B4532A;\n  --bs-btn-border-color: #B4532A;\n  --bs-btn-hover-bg: #8F3F1F;\n}","bs":true,"task":{"q":"Buat kartu tampil gelap dengan menambahkan atribut <code>data-bs-theme=\"dark\"</code> pada <code>#kotak</code>.","test":"document.getElementById('kotak').getAttribute('data-bs-theme')==='dark'","hint":"Tulis data-bs-theme=\"dark\" di tag div#kotak."},"pts":["Variabel --bs-* bisa ditimpa di CSS.","Sass: ubah $primary dll. sebelum import Bootstrap.","data-bs-theme=\"dark\" untuk mode gelap."],"q":[["Cara paling menyeluruh mengganti warna primer Bootstrap?",["Mengubah $primary di Sass sebelum import","Menambah !important di setiap tombol","Mengedit bootstrap.min.css"],0,"Sass membangun ulang semua komponen dengan nilai baru."]],"so":[{"q":"Ubah sudut membulat semua komponen menjadi lebih besar lewat variabel CSS.","h":"Timpa --bs-border-radius (dan variannya) di :root.","a":"<style>\n  :root {\n    --bs-border-radius: .75rem;\n    --bs-border-radius-lg: 1rem;\n    --bs-border-radius-sm: .5rem;\n  }\n</style>","lang":"html"},{"q":"Tulis file Sass yang mengganti warna primer menjadi #B4532A dan font dasar menjadi Inter.","h":"Variabel Sass ditulis sebelum @import bootstrap.","a":"// main.scss\n$primary: #B4532A;\n$font-family-base: \"Inter\", system-ui, sans-serif;\n\n@import \"bootstrap/scss/bootstrap\";","lang":"html"}],"deep":{"ist":[["Sass variables","$primary, $border-radius, $font-family-base diubah sebelum impor Bootstrap."],["CSS custom properties","--bs-primary, --bs-body-bg dapat diubah saat runtime."],["data-bs-theme","Atribut \"light\" / \"dark\" untuk mode warna (Bootstrap 5.3+)."],["Utility API","Membuat utilitas sendiri dari map Sass."],["Theming / white-label","Satu basis kode, banyak merek dengan variabel berbeda."]],"cx":[{"t":"Kustomisasi merek dan tombol tema","code":"// custom.scss\n$primary: #0f766e;\n$border-radius: .75rem;\n$font-family-sans-serif: \"Plus Jakarta Sans\", system-ui, sans-serif;\n$enable-shadows: true;\n@import \"bootstrap/scss/bootstrap\";\n\n// Utilitas baru: .opacity-15\n$utilities: map-merge($utilities, (\"opacity\": (property: opacity, values: (15: .15, 50: .5, 100: 1))));\n\n/* Ubah saat runtime tanpa compile ulang */\n.tema-kopi { --bs-primary: #92400e; --bs-primary-rgb: 146, 64, 14; }\n\n<!-- Tombol mode gelap -->\n<button class=\"btn btn-outline-secondary\" id=\"tombolTema\" aria-pressed=\"false\"><i class=\"bi bi-moon\"></i> Mode gelap</button>\n<script>\n  const simpan = (() => { try { return localStorage.getItem(\"tema\"); } catch { return null; } })();\n  const awal = simpan ?? (matchMedia(\"(prefers-color-scheme: dark)\").matches ? \"dark\" : \"light\");\n  const terapkan = (t) => { document.documentElement.dataset.bsTheme = t; tombolTema.setAttribute(\"aria-pressed\", t === \"dark\"); };\n  terapkan(awal);\n  tombolTema.onclick = () => { const t = document.documentElement.dataset.bsTheme === \"dark\" ? \"light\" : \"dark\"; terapkan(t); try { localStorage.setItem(\"tema\", t); } catch {} };\n</script>","lang":"scss"},{"t":"Menurunkan warna hover dan subtle seperti fungsi Sass Bootstrap","code":"const hexKeRgb = (h) => h.match(/\\w\\w/g).map((x) => parseInt(x, 16));\nconst rgbKeHex = (a) => \"#\" + a.map((x) => Math.round(x).toString(16).padStart(2, \"0\")).join(\"\");\nconst campur = (a, b, persenA) => rgbKeHex(hexKeRgb(a).map((v, i) => v * persenA + hexKeRgb(b)[i] * (1 - persenA)));\nconst shade = (h, p) => campur(\"#000000\", h, p), tint = (h, p) => campur(\"#ffffff\", h, p);\nconst primary = \"#0f766e\";\nconst baris = (k, v) => console.log(k.padEnd(22), v);\nbaris(\"primary\", primary);\nbaris(\"hover (shade 15%)\", shade(primary, 0.15));\nbaris(\"active (shade 20%)\", shade(primary, 0.2));\nbaris(\"subtle bg (tint 80%)\", tint(primary, 0.8));\nbaris(\"--bs-primary-rgb\", hexKeRgb(primary).join(\", \"));","lang":"js","out":"primary                #0f766e\nhover (shade 15%)      #0d645e\nactive (shade 20%)     #0c5e58\nsubtle bg (tint 80%)   #cfe4e2\n--bs-primary-rgb       15, 118, 110"}]}},{"b":["Gabungkan navbar, hero, grid kartu yang responsif, dan footer.","Perhatikan grid: <code>row-cols-1 row-cols-md-3</code> adalah cara singkat membuat semua kolom anak sama lebar.","Tantangan: tambahkan kartu kursus keempat dan ubah grid menjadi empat kolom di layar <code>lg</code> dengan <code>row-cols-lg-4</code>."],"html":"<nav class=\"navbar bg-body-tertiary border-bottom\"><div class=\"container\"><span class=\"navbar-brand fw-bold\">RuangKode</span><a class=\"btn btn-sm btn-primary\">Daftar</a></div></nav>\n<header class=\"container py-5 text-center\">\n  <h1 class=\"display-5 fw-bold\">Jadi developer mobile</h1>\n  <p class=\"lead text-body-secondary\">Belajar Dart, Flutter, Kotlin, dan Compose dari nol.</p>\n</header>\n<section class=\"container pb-5\">\n  <div id=\"kursus\" class=\"row row-cols-1 row-cols-md-3 g-3\">\n    <div class=\"col\"><div class=\"card h-100\"><div class=\"card-body\"><h5 class=\"card-title\">Dart</h5><p class=\"card-text\">Bahasa di balik Flutter.</p></div></div></div>\n    <div class=\"col\"><div class=\"card h-100\"><div class=\"card-body\"><h5 class=\"card-title\">Flutter</h5><p class=\"card-text\">Satu kode untuk Android dan iOS.</p></div></div></div>\n    <div class=\"col\"><div class=\"card h-100\"><div class=\"card-body\"><h5 class=\"card-title\">Kotlin</h5><p class=\"card-text\">Bahasa resmi Android.</p></div></div></div>\n  </div>\n</section>\n<footer class=\"border-top py-3 text-center small text-body-secondary\">© 2026 RuangKode</footer>","bs":true,"task":{"q":"Tambahkan kartu keempat di <code>#kursus</code> dan kelas <code>row-cols-lg-4</code>.","test":"(g=>g.children.length>=4&&g.classList.contains('row-cols-lg-4'))(document.getElementById('kursus'))","hint":"Salin satu div.col, ubah judulnya, lalu tambahkan row-cols-lg-4 pada div#kursus."},"pts":["row-cols-* menyamakan lebar semua kolom anak.","card h-100 membuat tinggi kartu seragam."],"q":[["Tailwind dan Bootstrap, mana yang menyediakan komponen siap pakai seperti modal?",["Bootstrap","Tailwind","Keduanya sama persis"],0,"Tailwind fokus pada utilitas; Bootstrap menyertakan komponen dan JS-nya."]],"so":[{"q":"Tambahkan bagian FAQ memakai accordion Bootstrap dengan dua pertanyaan.","h":"accordion > accordion-item > accordion-header (button) + accordion-collapse.","a":"<div class=\"accordion container mb-5\" id=\"faq\">\n  <div class=\"accordion-item\">\n    <h2 class=\"accordion-header\"><button class=\"accordion-button\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#q1\">Apakah gratis?</button></h2>\n    <div id=\"q1\" class=\"accordion-collapse collapse show\" data-bs-parent=\"#faq\"><div class=\"accordion-body\">Ya, semua materi gratis.</div></div>\n  </div>\n  <div class=\"accordion-item\">\n    <h2 class=\"accordion-header\"><button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#q2\">Perlu instal sesuatu?</button></h2>\n    <div id=\"q2\" class=\"accordion-collapse collapse\" data-bs-parent=\"#faq\"><div class=\"accordion-body\">Cukup browser untuk sebagian besar latihan.</div></div>\n  </div>\n</div>","lang":"html"}],"deep":{"ist":[["Landing kursus","Hero, silabus, mentor, testimoni, harga, FAQ, CTA."],["Accordion silabus","Menampilkan modul secara ringkas, dapat dibuka satu per satu."],["Schema.org Course","Data terstruktur agar kursus tampil kaya di hasil Google."],["Lighthouse 90+","Target skor performa, aksesibilitas, praktik terbaik, dan SEO."]],"cx":[{"t":"Kerangka halaman kursus","code":"<nav class=\"navbar navbar-expand-lg sticky-top bg-body border-bottom\">...</nav>\n<header class=\"py-5 bg-body-tertiary\">\n  <div class=\"container\"><div class=\"row align-items-center g-5\">\n    <div class=\"col-lg-6\">\n      <span class=\"badge text-bg-success mb-3\">Batch 12 · Mulai 6 Januari 2027</span>\n      <h1 class=\"display-5 fw-bold\">Bootcamp Frontend 16 Minggu</h1>\n      <p class=\"lead\">HTML, CSS, JavaScript, React, dan proyek portofolio dengan mentor industri.</p>\n      <div class=\"d-grid d-sm-flex gap-2\"><a class=\"btn btn-primary btn-lg\" href=\"#harga\">Daftar</a><a class=\"btn btn-outline-secondary btn-lg\" href=\"#silabus\">Lihat silabus</a></div>\n    </div>\n    <div class=\"col-lg-6\"><img class=\"img-fluid rounded-4\" src=\"hero.webp\" alt=\"Siswa bootcamp\" width=\"720\" height=\"480\"></div>\n  </div></div>\n</header>\n<section id=\"silabus\" class=\"container py-5\">\n  <div class=\"accordion\" id=\"silabusAcc\">\n    <div class=\"accordion-item\">\n      <h2 class=\"accordion-header\"><button class=\"accordion-button\" data-bs-toggle=\"collapse\" data-bs-target=\"#m1\">Minggu 1-3 · HTML & CSS</button></h2>\n      <div id=\"m1\" class=\"accordion-collapse collapse show\" data-bs-parent=\"#silabusAcc\"><div class=\"accordion-body\">Semantik, flexbox, grid, responsif.</div></div>\n    </div>\n  </div>\n</section>\n<script type=\"application/ld+json\">\n{ \"@context\": \"https://schema.org\", \"@type\": \"Course\", \"name\": \"Bootcamp Frontend 16 Minggu\",\n  \"description\": \"HTML sampai React dengan proyek portofolio.\", \"provider\": { \"@type\": \"Organization\", \"name\": \"RuangKode\" },\n  \"offers\": { \"@type\": \"Offer\", \"price\": \"4500000\", \"priceCurrency\": \"IDR\" } }\n</script>","lang":"html"},{"t":"Membuat data silabus dan JSON-LD dari satu sumber","code":"const modul = [[\"HTML & CSS\", 3], [\"JavaScript\", 4], [\"Git & tooling\", 1], [\"React\", 5], [\"Proyek akhir\", 3]];\nlet minggu = 1;\nfor (const [nama, durasi] of modul) {\n  const rentang = durasi === 1 ? String(minggu) : `${minggu}-${minggu + durasi - 1}`;\n  console.log(`Minggu ${rentang.padEnd(5)} · ${nama}`);\n  minggu += durasi;\n}\nconst jsonld = { \"@context\": \"https://schema.org\", \"@type\": \"Course\", name: \"Bootcamp Frontend 16 Minggu\",\n  hasCourseInstance: { \"@type\": \"CourseInstance\", courseMode: \"online\", courseWorkload: `P${minggu - 1}W` },\n  offers: { \"@type\": \"Offer\", price: \"4500000\", priceCurrency: \"IDR\" } };\nconsole.log(`total ${minggu - 1} minggu`);\nconsole.log(JSON.stringify(jsonld));","lang":"js","out":"Minggu 1-3   · HTML & CSS\nMinggu 4-7   · JavaScript\nMinggu 8     · Git & tooling\nMinggu 9-13  · React\nMinggu 14-16 · Proyek akhir\ntotal 16 minggu\n{\"@context\":\"https://schema.org\",\"@type\":\"Course\",\"name\":\"Bootcamp Frontend 16 Minggu\",\"hasCourseInstance\":{\"@type\":\"CourseInstance\",\"courseMode\":\"online\",\"courseWorkload\":\"P16W\"},\"offers\":{\"@type\":\"Offer\",\"price\":\"4500000\",\"priceCurrency\":\"IDR\"}}"}]}},{"b":["<b>Dropdown</b>: tombol dengan <code>data-bs-toggle=\"dropdown\"</code> dan daftar <code>.dropdown-menu</code> berisi <code>.dropdown-item</code>.","<b>Tab</b>: <code>.nav.nav-tabs</code> berisi tombol <code>data-bs-toggle=\"tab\"</code> yang menunjuk ke <code>.tab-pane</code> di dalam <code>.tab-content</code>.","<b>Accordion</b>: daftar bagian yang bisa dilipat. Tambahkan <code>data-bs-parent</code> agar hanya satu bagian terbuka dalam satu waktu. Semua ini berjalan tanpa JavaScript tambahan."],"html":"<div class=\"container py-3\">\n  <div class=\"dropdown mb-3\">\n    <button class=\"btn btn-secondary dropdown-toggle\" data-bs-toggle=\"dropdown\" aria-expanded=\"false\">Urutkan</button>\n    <ul class=\"dropdown-menu\">\n      <li><a class=\"dropdown-item\" href=\"#\">Termurah</a></li>\n      <li><a class=\"dropdown-item\" href=\"#\">Terbaru</a></li>\n    </ul>\n  </div>\n  <ul class=\"nav nav-tabs\" role=\"tablist\">\n    <li class=\"nav-item\"><button class=\"nav-link active\" data-bs-toggle=\"tab\" data-bs-target=\"#deskripsi\" type=\"button\" role=\"tab\">Deskripsi</button></li>\n    <li class=\"nav-item\"><button class=\"nav-link\" data-bs-toggle=\"tab\" data-bs-target=\"#ulasan\" type=\"button\" role=\"tab\">Ulasan</button></li>\n  </ul>\n  <div id=\"isiTab\" class=\"tab-content border border-top-0 p-3\">\n    <div class=\"tab-pane fade show active\" id=\"deskripsi\" role=\"tabpanel\">Kopi arabika 250 gram.</div>\n    <div class=\"tab-pane fade\" id=\"ulasan\" role=\"tabpanel\">★★★★★ Enak sekali.</div>\n  </div>\n</div>","bs":true,"task":{"q":"Tambahkan tab ketiga \"Pengiriman\" lengkap dengan tab-pane berisi teksnya.","test":"document.querySelectorAll('.nav-tabs .nav-link').length>=3&&document.querySelectorAll('#isiTab .tab-pane').length>=3","hint":"Salin satu li.nav-item dan satu div.tab-pane, beri id baru, dan samakan data-bs-target dengan id itu."},"pts":["dropdown: data-bs-toggle=\"dropdown\".","tab: data-bs-toggle=\"tab\" + tab-pane.","accordion: data-bs-parent agar satu terbuka."],"q":[["Atribut accordion agar hanya satu bagian terbuka?",["data-bs-parent","data-single","aria-expanded"],0,"Menunjuk ke wadah accordion."]],"deep":{"ist":[["dropdown","Menu pilihan yang diposisikan Popper; dropdown-menu-end untuk rata kanan."],["nav-tabs / nav-pills","Navigasi tab dengan tab-pane sebagai isi."],["accordion","Panel lipat; data-bs-parent agar hanya satu terbuka."],["Keyboard support","Panah atas/bawah di dropdown, Esc menutup; sudah ditangani Bootstrap."]],"cx":[{"t":"Dropdown akun, tab detail produk, dan FAQ","code":"<div class=\"dropdown\">\n  <button class=\"btn btn-light dropdown-toggle\" data-bs-toggle=\"dropdown\" aria-expanded=\"false\">\n    <img src=\"avatar.webp\" class=\"rounded-circle\" width=\"28\" height=\"28\" alt=\"\"> Rina\n  </button>\n  <ul class=\"dropdown-menu dropdown-menu-end\">\n    <li><a class=\"dropdown-item\" href=\"/akun\"><i class=\"bi bi-person\"></i> Profil</a></li>\n    <li><a class=\"dropdown-item\" href=\"/kelas-saya\">Kelas saya</a></li>\n    <li><hr class=\"dropdown-divider\"></li>\n    <li><button class=\"dropdown-item text-danger\">Keluar</button></li>\n  </ul>\n</div>\n\n<ul class=\"nav nav-tabs\" role=\"tablist\">\n  <li class=\"nav-item\" role=\"presentation\"><button class=\"nav-link active\" data-bs-toggle=\"tab\" data-bs-target=\"#desk\" role=\"tab\">Deskripsi</button></li>\n  <li class=\"nav-item\" role=\"presentation\"><button class=\"nav-link\" data-bs-toggle=\"tab\" data-bs-target=\"#ulasan\" role=\"tab\">Ulasan <span class=\"badge text-bg-secondary\">128</span></button></li>\n</ul>\n<div class=\"tab-content border border-top-0 p-3\">\n  <div class=\"tab-pane fade show active\" id=\"desk\" role=\"tabpanel\">...</div>\n  <div class=\"tab-pane fade\" id=\"ulasan\" role=\"tabpanel\">...</div>\n</div>\n\n<div class=\"accordion accordion-flush\" id=\"faq\">\n  <div class=\"accordion-item\">\n    <h2 class=\"accordion-header\"><button class=\"accordion-button collapsed\" data-bs-toggle=\"collapse\" data-bs-target=\"#q1\">Apakah ada sertifikat?</button></h2>\n    <div id=\"q1\" class=\"accordion-collapse collapse\" data-bs-parent=\"#faq\"><div class=\"accordion-body\">Ya, setelah lulus proyek akhir.</div></div>\n  </div>\n</div>","lang":"html"}]}},{"b":["<b>Offcanvas</b> adalah panel yang meluncur dari tepi layar, cocok untuk menu samping atau filter di ponsel. Dibuka dengan <code>data-bs-toggle=\"offcanvas\"</code>.","<b>Toast</b> adalah notifikasi kecil yang muncul lalu hilang. Toast dan <b>tooltip</b> perlu diaktifkan dengan JavaScript: <code>new bootstrap.Toast(el).show()</code> dan <code>new bootstrap.Tooltip(el)</code>.","Komponen yang perlu diaktifkan lewat JS ini disebut opt-in, karena demi performa Bootstrap tidak memasangnya otomatis."],"html":"<div class=\"container py-3 d-flex gap-2 flex-wrap\">\n  <button class=\"btn btn-outline-dark\" data-bs-toggle=\"offcanvas\" data-bs-target=\"#filter\">Filter</button>\n  <button id=\"btnToast\" class=\"btn btn-success\">Tambah ke keranjang</button>\n  <button id=\"info\" class=\"btn btn-outline-secondary\" data-bs-toggle=\"tooltip\" data-bs-title=\"Gratis ongkir di atas Rp100.000\">Info ongkir</button>\n</div>\n<div class=\"offcanvas offcanvas-start\" tabindex=\"-1\" id=\"filter\">\n  <div class=\"offcanvas-header\"><h5 class=\"offcanvas-title\">Filter</h5><button class=\"btn-close\" data-bs-dismiss=\"offcanvas\" aria-label=\"Tutup\"></button></div>\n  <div class=\"offcanvas-body\">Harga, kategori, rating...</div>\n</div>\n<div class=\"toast-container position-fixed bottom-0 end-0 p-3\">\n  <div id=\"notif\" class=\"toast\" role=\"status\" aria-live=\"polite\">\n    <div class=\"toast-body\">Produk ditambahkan ke keranjang.</div>\n  </div>\n</div>","js":"document.getElementById('btnToast').addEventListener('click', () => {\n  new bootstrap.Toast(document.getElementById('notif')).show();\n});\n// aktifkan tooltip di sini","bs":true,"task":{"q":"Aktifkan tooltip pada tombol <code>#info</code> dengan <code>new bootstrap.Tooltip(...)</code>, lalu tekan Jalankan dan Periksa.","test":"!!(window.bootstrap&&bootstrap.Tooltip.getInstance(document.getElementById('info')))","hint":"new bootstrap.Tooltip(document.getElementById('info'));"},"pts":["offcanvas untuk panel samping.","Toast dan tooltip diaktifkan dengan JS.","toast-container position-fixed untuk posisi."],"q":[["Komponen mana yang harus diaktifkan lewat JavaScript?",["Tooltip","Card","Grid"],0,"Tooltip dan popover bersifat opt-in."]],"deep":{"ist":[["offcanvas","Panel samping yang meluncur; cocok untuk filter atau keranjang di ponsel."],["toast","Notifikasi singkat yang hilang sendiri; letakkan dalam toast-container."],["tooltip / popover","Info tambahan saat hover/focus; wajib diinisialisasi dengan JS."],["aria-live","Agar pembaca layar mengumumkan toast."]],"cx":[{"t":"Keranjang offcanvas, toast, dan tooltip","code":"<button class=\"btn btn-primary position-relative\" data-bs-toggle=\"offcanvas\" data-bs-target=\"#keranjang\">\n  <i class=\"bi bi-cart\"></i><span class=\"position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger\">2</span>\n</button>\n<div class=\"offcanvas offcanvas-end\" tabindex=\"-1\" id=\"keranjang\" aria-labelledby=\"judulKeranjang\">\n  <div class=\"offcanvas-header\"><h5 id=\"judulKeranjang\">Keranjang</h5><button class=\"btn-close\" data-bs-dismiss=\"offcanvas\" aria-label=\"Tutup\"></button></div>\n  <div class=\"offcanvas-body\">...</div>\n</div>\n\n<div class=\"toast-container position-fixed bottom-0 end-0 p-3\">\n  <div id=\"toastSimpan\" class=\"toast\" role=\"status\" aria-live=\"polite\" aria-atomic=\"true\" data-bs-delay=\"3000\">\n    <div class=\"toast-body d-flex justify-content-between\">Kelas ditambahkan ke keranjang <button class=\"btn-close\" data-bs-dismiss=\"toast\"></button></div>\n  </div>\n</div>\n\n<span class=\"text-decoration-underline\" data-bs-toggle=\"tooltip\" data-bs-title=\"Pajak Pertambahan Nilai 11%\" tabindex=\"0\">PPN</span>\n\n<script>\n  document.querySelectorAll('[data-bs-toggle=\"tooltip\"]').forEach((el) => new bootstrap.Tooltip(el));\n  const toast = bootstrap.Toast.getOrCreateInstance(document.getElementById(\"toastSimpan\"));\n  document.querySelectorAll(\".tambah-keranjang\").forEach((b) => b.addEventListener(\"click\", () => toast.show()));\n</script>","lang":"html"}]}},{"b":["Tabel: <code>.table</code> lalu tambahan <code>.table-striped</code> (belang), <code>.table-hover</code>, <code>.table-sm</code>. Bungkus dengan <code>.table-responsive</code> agar tabel lebar bisa digulir di ponsel tanpa merusak halaman.","<b>List group</b> (<code>.list-group</code> dan <code>.list-group-item</code>) cocok untuk daftar pengaturan atau riwayat, dan bisa dipadukan dengan badge.","<b>Pagination</b> (<code>.pagination</code>, <code>.page-item</code>, <code>.page-link</code>) untuk berpindah halaman data. Tandai halaman aktif dengan <code>.active</code> dan <code>aria-current=\"page\"</code>."],"html":"<div class=\"container py-3\">\n  <div class=\"table-responsive\">\n    <table id=\"tabel\" class=\"table\">\n      <thead><tr><th>Produk</th><th class=\"text-end\">Harga</th><th class=\"text-end\">Stok</th></tr></thead>\n      <tbody>\n        <tr><td>Kopi Gayo</td><td class=\"text-end\">85.000</td><td class=\"text-end\">12</td></tr>\n        <tr><td>Kopi Toraja</td><td class=\"text-end\">90.000</td><td class=\"text-end\">4</td></tr>\n        <tr><td>Kopi Kintamani</td><td class=\"text-end\">80.000</td><td class=\"text-end\">0</td></tr>\n      </tbody>\n    </table>\n  </div>\n  <nav aria-label=\"Halaman produk\">\n    <ul class=\"pagination\">\n      <li class=\"page-item\"><a class=\"page-link\" href=\"#\">1</a></li>\n      <li class=\"page-item\"><a class=\"page-link\" href=\"#\">2</a></li>\n      <li class=\"page-item\"><a class=\"page-link\" href=\"#\">3</a></li>\n    </ul>\n  </nav>\n</div>","bs":true,"task":{"q":"Beri tabel kelas <code>table-striped</code> dan <code>table-hover</code>, lalu tandai halaman 1 sebagai aktif (<code>active</code> pada li pertama).","test":"(t=>t.classList.contains('table-striped')&&t.classList.contains('table-hover'))(document.getElementById('tabel'))&&document.querySelector('.pagination .page-item').classList.contains('active')","hint":"Tambahkan dua kelas pada table#tabel dan active pada li.page-item pertama."},"pts":["table + table-striped/hover, bungkus table-responsive.","list-group untuk daftar.","pagination dengan active dan aria-current."],"q":[["Kenapa tabel dibungkus .table-responsive?",["Agar bisa digulir horizontal di layar sempit","Agar berwarna","Agar bisa diurutkan"],0,"Halaman tidak ikut melebar."]],"deep":{"ist":[["table-striped / table-hover","Gaya tabel standar; table-responsive untuk scroll horizontal."],["list-group","Daftar dengan item aktif, badge, dan aksi."],["pagination","Navigasi halaman; tandai halaman aktif dengan aria-current."],["Server-side pagination","Hanya mengambil satu halaman data per request (LIMIT/OFFSET atau cursor)."]],"cx":[{"t":"Tabel transaksi dengan pagination","code":"<div class=\"table-responsive\">\n  <table class=\"table table-striped table-hover align-middle\">\n    <caption>Transaksi November 2026</caption>\n    <thead class=\"table-light\"><tr><th scope=\"col\">No. invoice</th><th scope=\"col\">Siswa</th><th scope=\"col\" class=\"text-end\">Total</th><th scope=\"col\">Status</th></tr></thead>\n    <tbody>\n      <tr><td>INV-0412</td><td>Rina W.</td><td class=\"text-end\">Rp399.000</td><td><span class=\"badge text-bg-success\">Lunas</span></td></tr>\n      <tr><td>INV-0413</td><td>Budi S.</td><td class=\"text-end\">Rp450.000</td><td><span class=\"badge text-bg-warning\">Menunggu</span></td></tr>\n    </tbody>\n  </table>\n</div>\n<nav aria-label=\"Navigasi halaman transaksi\">\n  <ul class=\"pagination justify-content-center\">\n    <li class=\"page-item disabled\"><span class=\"page-link\">«</span></li>\n    <li class=\"page-item active\" aria-current=\"page\"><span class=\"page-link\">1</span></li>\n    <li class=\"page-item\"><a class=\"page-link\" href=\"?hal=2\">2</a></li>\n    <li class=\"page-item\"><a class=\"page-link\" href=\"?hal=3\">3</a></li>\n    <li class=\"page-item\"><a class=\"page-link\" href=\"?hal=2\">»</a></li>\n  </ul>\n</nav>","lang":"html"},{"t":"Membuat nomor halaman dengan elipsis","code":"function halaman(aktif, total, sekitar = 1) {\n  const h = new Set([1, total]);\n  for (let i = aktif - sekitar; i <= aktif + sekitar; i++) if (i > 1 && i < total) h.add(i);\n  const urut = [...h].sort((a, b) => a - b), hasil = [];\n  urut.forEach((n, i) => { if (i && n - urut[i - 1] > 1) hasil.push(\"…\"); hasil.push(n === aktif ? `[${n}]` : String(n)); });\n  return hasil.join(\" \");\n}\nconst totalData = 487, perHalaman = 20, total = Math.ceil(totalData / perHalaman);\nfor (const a of [1, 5, 13, total]) console.log(`hal ${String(a).padStart(2)}/${total}: « ${halaman(a, total)} »   OFFSET ${(a - 1) * perHalaman} LIMIT ${perHalaman}`);","lang":"js","out":"hal  1/25: « [1] 2 … 25 »   OFFSET 0 LIMIT 20\nhal  5/25: « 1 … 4 [5] 6 … 25 »   OFFSET 80 LIMIT 20\nhal 13/25: « 1 … 12 [13] 14 … 25 »   OFFSET 240 LIMIT 20\nhal 25/25: « 1 … 24 [25] »   OFFSET 480 LIMIT 20"}]}},{"b":["<code>.hstack</code> dan <code>.vstack</code> adalah jalan pintas flexbox dengan <code>gap-*</code>. <code>.ms-auto</code> mendorong elemen ke kanan.","Posisi: <code>position-relative</code>, <code>position-absolute</code>, <code>top-0 start-100 translate-middle</code> untuk badge notifikasi di pojok tombol.","Rasio: <code>.ratio .ratio-16x9</code> menjaga video atau gambar tetap proporsional. <code>object-fit-cover</code> memotong gambar agar penuh tanpa gepeng."],"html":"<div class=\"container py-3\">\n  <div class=\"hstack gap-3 p-3 border rounded\">\n    <b>Keranjang</b>\n    <button id=\"lonceng\" class=\"btn btn-primary ms-auto\">\n      Notifikasi\n    </button>\n  </div>\n  <div class=\"ratio ratio-16x9 mt-3 bg-secondary-subtle rounded\"><div class=\"d-flex align-items-center justify-content-center\">Area video 16:9</div></div>\n</div>","bs":true,"task":{"q":"Tambahkan badge merah angka 3 di pojok kanan atas tombol: tombol diberi <code>position-relative</code>, badge diberi <code>position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger</code>.","test":"(b=>b.classList.contains('position-relative')&&!!b.querySelector('.badge.position-absolute.bg-danger'))(document.getElementById('lonceng'))","hint":"<span class=\"position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger\">3</span> di dalam tombol."},"pts":["hstack/vstack + gap.","position-* + translate-middle untuk badge pojok.","ratio-16x9 untuk proporsi tetap."],"q":[["Kelas yang mendorong elemen ke kanan di dalam flex?",["ms-auto","float-end","text-end"],0,"margin-start auto memakan ruang kosong."]],"deep":{"ist":[["vstack / hstack","Pembungkus flex vertikal/horizontal dengan gap; ringkas untuk tata letak cepat."],["Position utilities","position-absolute top-0 start-100 translate-middle untuk badge di sudut."],["ratio","Wadah berasio tetap (ratio-16x9) untuk video atau peta."],["object-fit-*","object-fit-cover agar gambar memenuhi wadah tanpa gepeng."],["visually-hidden","Teks hanya untuk pembaca layar."]],"cx":[{"t":"Profil mentor, video, dan tombol ikon","code":"<div class=\"hstack gap-3 align-items-start\">\n  <div class=\"position-relative flex-shrink-0\">\n    <img src=\"mentor.webp\" class=\"rounded-circle object-fit-cover\" width=\"64\" height=\"64\" alt=\"Dimas, mentor React\">\n    <span class=\"position-absolute bottom-0 end-0 p-2 bg-success border border-light rounded-circle\">\n      <span class=\"visually-hidden\">Sedang online</span>\n    </span>\n  </div>\n  <div class=\"vstack gap-1\">\n    <strong>Dimas Pratama</strong>\n    <span class=\"text-body-secondary small\">Senior Frontend Engineer · 8 tahun</span>\n  </div>\n  <button class=\"btn btn-light ms-auto\"><i class=\"bi bi-chat-dots\"></i><span class=\"visually-hidden\">Kirim pesan</span></button>\n</div>\n\n<div class=\"ratio ratio-16x9 rounded-3 overflow-hidden mt-4\">\n  <video controls preload=\"metadata\" poster=\"cuplikan.webp\"><source src=\"cuplikan.mp4\" type=\"video/mp4\"></video>\n</div>","lang":"html"},{"t":"Menghitung tinggi wadah rasio di berbagai lebar","code":"const rasio = { \"1x1\": [1, 1], \"4x3\": [4, 3], \"16x9\": [16, 9], \"21x9\": [21, 9] };\nfor (const lebar of [360, 768, 1140]) {\n  console.log(`lebar ${lebar}px: ` + Object.entries(rasio).map(([k, [w, h]]) => `${k} -> ${Math.round((lebar * h) / w)}px`).join(\" | \"));\n}\nconsole.log(\"padding-top trik lama untuk 16x9:\", ((9 / 16) * 100).toFixed(2) + \"%\", \"| kini cukup aspect-ratio: 16 / 9\");","lang":"js","out":"lebar 360px: 1x1 -> 360px | 4x3 -> 270px | 16x9 -> 203px | 21x9 -> 154px\nlebar 768px: 1x1 -> 768px | 4x3 -> 576px | 16x9 -> 432px | 21x9 -> 329px\nlebar 1140px: 1x1 -> 1140px | 4x3 -> 855px | 16x9 -> 641px | 21x9 -> 489px\npadding-top trik lama untuk 16x9: 56.25% | kini cukup aspect-ratio: 16 / 9"}]}}]);
